import{_ as a,o as i,c as t,a8 as r}from"./chunks/framework.CiGKN4gy.js";const b=JSON.parse('{"title":"5.x.x","description":"","frontmatter":{"title":"5.x.x","lang":"en"},"headers":[],"relativePath":"changes/5_x_x.md","filePath":"changes/5_x_x.md","lastUpdated":1790353258000}'),d={name:"changes/5_x_x.md"};function o(l,e,n,h,c,s){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjI1LngueCUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzUzMjU4MDAwJTdE"},[...e[0]||(e[0]=[r('<h1 id="change-log-5-x-x" tabindex="-1">Change Log (5.x.x) <a class="header-anchor" href="#change-log-5-x-x" aria-label="Permalink to &quot;Change Log (5.x.x)&quot;">​</a></h1><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><div class="tip custom-block"><p class="custom-block-title">What is a breaking change?</p><ul><li>The original configuration file may not work, for example, if a directive item is removed or renamed.</li><li>It may be necessary to update the build environment, such as installing new dependencies.</li></ul></div><h2 id="_5-5-1-2021-07-16-utc-0800" tabindex="-1">[5.5.1] - 2021-07-16 UTC+0800 <a class="header-anchor" href="#_5-5-1-2021-07-16-utc-0800" aria-label="Permalink to &quot;[5.5.1] - 2021-07-16 UTC+0800&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Segmentation fault.</p></li><li><p>Memory leak.</p></li></ul><hr><h2 id="_5-5-0-2021-06-25-utc-0800" tabindex="-1">[5.5.0] - 2021-06-25 UTC+0800 <a class="header-anchor" href="#_5-5-0-2021-06-25-utc-0800" aria-label="Permalink to &quot;[5.5.0] - 2021-06-25 UTC+0800&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Because of high false positives, <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>-based XSS attack detection has been disabled in working modes <code>STD</code> and <code>DYNAMIC</code>.</li></ul><hr><h2 id="_5-4-2-2021-06-15-utc-0800" tabindex="-1">[5.4.2] - 2021-06-15 UTC+0800 <a class="header-anchor" href="#_5-4-2-2021-06-15-utc-0800" aria-label="Permalink to &quot;[5.4.2] - 2021-06-15 UTC+0800&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>When POST inspection is enabled, POST requests are not logged in the access log.</li></ul><hr><h2 id="_5-4-1-2021-06-09-utc-0800" tabindex="-1">[5.4.1] - 2021-06-09 UTC+0800 <a class="header-anchor" href="#_5-4-1-2021-06-09-utc-0800" aria-label="Permalink to &quot;[5.4.1] - 2021-06-09 UTC+0800&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The value of built-in variables may be wrong when the directive <code>error_page</code> is used.</li></ul><hr><h2 id="_5-4-0-2021-06-03-utc-0800" tabindex="-1">[5.4.0] - 2021-06-03 UTC+0800 <a class="header-anchor" href="#_5-4-0-2021-06-03-utc-0800" aria-label="Permalink to &quot;[5.4.0] - 2021-06-03 UTC+0800&quot;">​</a></h2><h3 id="note" tabindex="-1"><strong>NOTE</strong> <a class="header-anchor" href="#note" aria-label="Permalink to &quot;**NOTE**&quot;">​</a></h3><p><strong>The clone link for <code>libinjection</code> has been replaced in this release. The new link is <a href="https://github.com/libinjection/libinjection.git" target="_blank" rel="noreferrer">https://github.com/libinjection/libinjection.git</a>.</strong></p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Anti XSS (powered by <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Add debug log related to built-in variable calculation.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>POST inspection is not working.</li></ul><hr><h2 id="_5-3-2-2021-05-28-utc-0800" tabindex="-1">[5.3.2] - 2021-05-28 UTC+0800 <a class="header-anchor" href="#_5-3-2-2021-05-28-utc-0800" aria-label="Permalink to &quot;[5.3.2] - 2021-05-28 UTC+0800&quot;">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Memory corruption.</li></ul><hr><h2 id="_5-3-1-2021-05-26-gmt-0800" tabindex="-1">[5.3.1] - 2021-05-26 GMT+0800 <a class="header-anchor" href="#_5-3-1-2021-05-26-gmt-0800" aria-label="Permalink to &quot;[5.3.1] - 2021-05-26 GMT+0800&quot;">​</a></h2><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Sometimes the module does not compile even if the dependencies are installed correctly.</li></ul><hr><h2 id="_5-3-0-2021-05-16-gmt-0800" tabindex="-1">[5.3.0] - 2021-05-16 GMT+0800 <a class="header-anchor" href="#_5-3-0-2021-05-16-gmt-0800" aria-label="Permalink to &quot;[5.3.0] - 2021-05-16 GMT+0800&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>New directive: <code>waf_under_attack</code>, which can be used when the site is under attack.</p></li><li><p>New directive: <code>waf_http_status</code>, which sets the HTTP status code returned when a request is blocked.</p></li><li><p>New built-in variable: <code>$waf_blocking_log</code>, not an empty string when the request is blocked for its value.</p></li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Update default rules.</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>CC protection sometimes not work.</p></li><li><p>Cookie inspection sometimes not work.</p></li></ul><hr><h2 id="_5-1-2-2021-04-30-gmt-0800" tabindex="-1">[5.1.2] - 2021-04-30 GMT+0800 <a class="header-anchor" href="#_5-1-2-2021-04-30-gmt-0800" aria-label="Permalink to &quot;[5.1.2] - 2021-04-30 GMT+0800&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Support for detecting SQL injection (powered by <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>). This feature can be enabled by enabling the mode <code>LIB-INJECTION</code>, see the documentation for details.</li></ul><hr><h2 id="_5-1-1-2021-04-23-gmt-0800" tabindex="-1">[5.1.1] - 2021-04-23 GMT+0800 <a class="header-anchor" href="#_5-1-1-2021-04-23-gmt-0800" aria-label="Permalink to &quot;[5.1.1] - 2021-04-23 GMT+0800&quot;">​</a></h2><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>URL and Referer whitelist are not working.</li></ul><hr><h2 id="_5-1-0-2021-04-20-gmt-0800" tabindex="-1">[5.1.0] - 2021-04-20 GMT+0800 <a class="header-anchor" href="#_5-1-0-2021-04-20-gmt-0800" aria-label="Permalink to &quot;[5.1.0] - 2021-04-20 GMT+0800&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>New built-in variable <code>waf_log</code>, which is not an empty string when this module has performed a inspection, but an empty string otherwise, mainly used in the directive <code>access_log</code>.</p></li><li><p>New built-in variable <code>waf_spend</code>, which records the time (in milliseconds) taken by this module to perform the inspection.</p></li></ul><hr><h2 id="_5-0-0-2021-04-07-gmt-0800" tabindex="-1">[5.0.0] - 2021-04-07 GMT+0800 <a class="header-anchor" href="#_5-0-0-2021-04-07-gmt-0800" aria-label="Permalink to &quot;[5.0.0] - 2021-04-07 GMT+0800&quot;">​</a></h2><h3 id="warning" tabindex="-1"><strong>WARNING</strong> <a class="header-anchor" href="#warning" aria-label="Permalink to &quot;**WARNING**&quot;">​</a></h3><p><strong>This version contains breaking changes.</strong></p><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>A new mode <code>CACHE</code> has been added, enabling this mode will cache the results of each inspection to improve performance.</p></li><li><p>New configuration <code>waf_cache</code> has been added to set parameters related to cache.</p></li><li><p>Added directive <code>waf_cc_deny</code> to set CC protection related parameters.</p></li><li><p>New directive <code>waf_priority</code> has been added to set the priority of all checks except for POST checks.</p></li><li><p>The <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Retry-After" target="_blank" rel="noreferrer">Retry-Afte</a> response header is appended when the CC protection returns a 503 status code.</p></li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>The directive <code>waf_cc_deny_limit</code> is deprecated and replaced with the new directive <code>waf_cc_deny</code>.</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Swaps the default priority of CC protection and IP whitelist inspection.</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Fixed a segmentation fault when the number of worker processes is greater than one.</p></li><li><p>Fixed a bug where CC protection statistics were sometimes inaccurate.</p></li></ul>',68)])])}const m=a(d,[["render",o]]);export{b as __pageData,m as default};
